    ///
    /// 解析流程：
    /// 1. 验证 ELF 头（必须是 RISC-V 64 位可执行文件）
    /// 2. 遍历 LOAD 类型的程序段，映射到新地址空间
    /// 3. 记录最高虚拟地址作为堆底
    /// 4. 分配并映射用户栈（2 页 = 8 KiB）
    /// 5. 映射异界传送门页面
    /// 6. 创建用户态上下文，设置入口地址和栈指针
    pub fn from_elf(elf: ElfFile) -> Option<Self> {
