   117→    /// Return number of blocks needed include indirect1/2.
   118→    pub fn total_blocks(size: u32) -> u32 {
   119→        let data_blocks = Self::_data_blocks(size) as usize;
   120→        let mut total = data_blocks;
   121→        // indirect1：数据块数量超过 direct 容量时，需要额外 1 个一级索引块
   122→        if data_blocks > INODE_DIRECT_COUNT {
   123→            total += 1;
   124→        }
   125→        // indirect2：超过一级索引覆盖范围后，需要二级索引块和若干一级索引块
   126→        if data_blocks > INDIRECT1_BOUND {
   127→            total += 1;
