   129→            total += (data_blocks - INDIRECT1_BOUND).div_ceil(INODE_INDIRECT1_COUNT);
   130→        }
   131→        total as u32
   132→    }
   133→    /// Get the number of data blocks that have to be allocated given the new size of data
   134→    pub fn blocks_num_needed(&self, new_size: u32) -> u32 {
   135→        assert!(new_size >= self.size);
   136→        Self::total_blocks(new_size) - Self::total_blocks(self.size)
   137→    }
