   151→            let indirect1 = get_block_cache(self.indirect2 as usize, Arc::clone(block_device))
   152→                .lock()
   153→                .read(0, |indirect2: &IndirectBlock| {
   154→                    indirect2[last / INODE_INDIRECT1_COUNT]
   155→                });
   156→            get_block_cache(indirect1 as usize, Arc::clone(block_device))
   157→                .lock()
   158→                .read(0, |indirect1: &IndirectBlock| {
