   188→        }
   189→        // 将剩余数据块号写入一级索引块
   190→        get_block_cache(self.indirect1 as usize, Arc::clone(block_device))
   191→            .lock()
   192→            .modify(0, |indirect1: &mut IndirectBlock| {
   193→                while current_blocks < total_blocks.min(INODE_INDIRECT1_COUNT as u32) {
   194→                    indirect1[current_blocks as usize] = new_blocks.next().unwrap();
   195→                    current_blocks += 1;
   196→                }
   197→            });
