   225→                            indirect1[b0] = new_blocks.next().unwrap();
   226→                        });
   227→                    // move to next
   228→                    b0 += 1;
   229→                    if b0 == INODE_INDIRECT1_COUNT {
   230→                        b0 = 0;
   231→                        a0 += 1;
   232→                    }
   233→                }
