   310→    /// Read data from current disk inode
   311→    pub fn read_at(
   312→        &self,
   313→        offset: usize,
   314→        buf: &mut [u8],
   315→        block_device: &Arc<dyn BlockDevice>,
   316→    ) -> usize {
   317→        let mut start = offset;
   318→        let end = (offset + buf.len()).min(self.size as usize);
   319→        if start >= end {
   320→            return 0;
   321→        }
   322→        let mut start_block = start / BLOCK_SZ;
   323→        let mut read_size = 0usize;
   324→        loop {
   325→            // calculate end of current block
   326→            let mut end_current_block = (start / BLOCK_SZ + 1) * BLOCK_SZ;
   327→            end_current_block = end_current_block.min(end);
   328→            // read and update read size
   329→            let block_read_size = end_current_block - start;
   330→            let dst = &mut buf[read_size..read_size + block_read_size];
   331→            get_block_cache(
   332→                self.get_block_id(start_block as u32, block_device) as usize,
   333→                Arc::clone(block_device),
   334→            )
   335→            .lock()
   336→            .read(0, |data_block: &DataBlock| {
   337→                let src = &data_block[start % BLOCK_SZ..start % BLOCK_SZ + block_read_size];
   338→                dst.copy_from_slice(src);
   339→            });
   340→            read_size += block_read_size;
   341→            // move to next block
   342→            if end_current_block == end {
   343→                break;
   344→            }
   345→            start_block += 1;
   346→            start = end_current_block;
   347→        }
   348→        read_size
   349→    }
   350→    /// Write data into current disk inode
   351→    /// size must be adjusted properly beforehand
   352→    pub fn write_at(
   353→        &mut self,
   354→        offset: usize,
   355→        buf: &[u8],
   356→        block_device: &Arc<dyn BlockDevice>,
   357→    ) -> usize {
   358→        let mut start = offset;
   359→        let end = (offset + buf.len()).min(self.size as usize);
   360→        assert!(start <= end);
   361→        let mut start_block = start / BLOCK_SZ;
   362→        let mut write_size = 0usize;
   363→        loop {
   364→            // calculate end of current block
   365→            let mut end_current_block = (start / BLOCK_SZ + 1) * BLOCK_SZ;
   366→            end_current_block = end_current_block.min(end);
   367→            // write and update write size
   368→            let block_write_size = end_current_block - start;
   369→            get_block_cache(
   370→                self.get_block_id(start_block as u32, block_device) as usize,
   371→                Arc::clone(block_device),
   372→            )
   373→            .lock()
   374→            .modify(0, |data_block: &mut DataBlock| {
   375→                let src = &buf[write_size..write_size + block_write_size];
   376→                let dst = &mut data_block[start % BLOCK_SZ..start % BLOCK_SZ + block_write_size];
   377→                dst.copy_from_slice(src);
   378→            });
   379→            write_size += block_write_size;
   380→            // move to next block
   381→            if end_current_block == end {
   382→                break;
   383→            }
   384→            start_block += 1;
   385→            start = end_current_block;
   386→        }
