     8→///An easy file system on block
     9→pub struct EasyFileSystem {
    10→    ///Real device
    11→    pub block_device: Arc<dyn BlockDevice>,
    12→    ///Inode bitmap
    13→    pub inode_bitmap: Bitmap,
    14→    ///Data bitmap
    15→    pub data_bitmap: Bitmap,
