    93→        let blocks_needed = disk_inode.blocks_num_needed(new_size);
    94→        let mut v: Vec<u32> = Vec::new();
    95→        for _ in 0..blocks_needed {
    96→            v.push(fs.alloc_data());
    97→        }
    98→        disk_inode.increase_size(new_size, v, &self.block_device);
    99→    }
