   142→    /// List inodes by id under current inode
   143→    pub fn readdir(&self) -> Vec<String> {
   144→        let _fs = self.fs.lock();
   145→        self.read_disk_inode(|disk_inode| {
   146→            let file_count = (disk_inode.size as usize) / DIRENT_SZ;
