   107→// 内核入口，栈 = 32 页 = 128 KiB。
   108→//
   109→// 这里不再调用 tg_linker::boot0! 宏，避免外部已发布版本与 Rust 2024
   110→// 在属性语义上的兼容差异影响本 crate 的发布校验。
   111→#[cfg(target_arch = "riscv64")]
   112→#[unsafe(naked)]
   113→#[unsafe(no_mangle)]
   114→#[unsafe(link_section = ".text.entry")]
   115→unsafe extern "C" fn _start() -> ! {
   116→    const STACK_SIZE: usize = 32 * 4096;
   117→    #[unsafe(link_section = ".boot.stack")]
   118→    static mut STACK: [u8; STACK_SIZE] = [0u8; STACK_SIZE];
   119→
   120→    core::arch::naked_asm!(
   121→        "la sp, {stack} + {stack_size}",
   122→        "j  {main}",
   123→        stack = sym STACK,
   124→        stack_size = const STACK_SIZE,
   125→        main = sym rust_main,
   126→    )
   127→}
