   134→/// 内核地址空间的全局存储
   135→struct KernelSpace {
   136→    inner: UnsafeCell<MaybeUninit<AddressSpace<Sv39, Sv39Manager>>>,
   137→}
   138→
   139→unsafe impl Sync for KernelSpace {}
   140→
   141→impl KernelSpace {
   142→    const fn new() -> Self {
   143→        Self {
   144→            inner: UnsafeCell::new(MaybeUninit::uninit()),
   145→        }
   146→    }
   147→
   148→    unsafe fn write(&self, space: AddressSpace<Sv39, Sv39Manager>) {
   149→        unsafe { *self.inner.get() = MaybeUninit::new(space) };
   150→    }
   151→
   152→    unsafe fn assume_init_ref(&self) -> &AddressSpace<Sv39, Sv39Manager> {
   153→        unsafe { &*(*self.inner.get()).as_ptr() }
   154→    }
   155→}
