   163→/// 内核主函数
   164→///
   165→/// 与第七章相比：
   166→/// - 新增 `init_thread`（线程系统调用）和 `init_sync_mutex`（同步原语系统调用）
   167→/// - 使用 `PThreadManager`（双层管理器）替代 `PManager`
   168→/// - 初始化时同时创建 Process 和 Thread
   169→/// - 主循环中新增**线程阻塞**处理（SEMAPHORE_DOWN/MUTEX_LOCK/CONDVAR_WAIT）
   170→extern "C" fn rust_main() -> ! {
   171→    let layout = tg_linker::KernelLayout::locate();
   172→    // 步骤 1：BSS 清零
   173→    unsafe { layout.zero_bss() };
   174→    // 步骤 2：控制台和日志
   175→    tg_console::init_console(&Console);
   176→    tg_console::set_log_level(option_env!("LOG"));
   177→    tg_console::test_log();
   178→    // 步骤 3：堆分配器
   179→    tg_kernel_alloc::init(layout.start() as _);
   180→    unsafe {
   181→        tg_kernel_alloc::transfer(core::slice::from_raw_parts_mut(
   182→            layout.end() as _,
   183→            MEMORY - layout.len(),
   184→        ))
   185→    };
   186→    // 步骤 4：异界传送门
   187→    let portal_size = MultislotPortal::calculate_size(1);
   188→    let portal_layout = Layout::from_size_align(portal_size, 1 << Sv39::PAGE_BITS).unwrap();
   189→    let portal_ptr = unsafe { alloc(portal_layout) };
   190→    assert!(portal_layout.size() < 1 << Sv39::PAGE_BITS);
   191→    // 步骤 5：内核地址空间
   192→    kernel_space(layout, MEMORY, portal_ptr as _);
   193→    // 步骤 6：异界传送门初始化
   194→    let portal = unsafe { MultislotPortal::init_transit(PROTAL_TRANSIT.base().val(), 1) };
   195→    // 步骤 7：系统调用初始化
   196→    tg_syscall::init_io(&SyscallContext);
   197→    tg_syscall::init_process(&SyscallContext);
   198→    tg_syscall::init_scheduling(&SyscallContext);
   199→    tg_syscall::init_clock(&SyscallContext);
   200→    tg_syscall::init_signal(&SyscallContext);
   201→    tg_syscall::init_thread(&SyscallContext);       // 本章新增：线程系统调用
   202→    tg_syscall::init_sync_mutex(&SyscallContext);   // 本章新增：同步原语系统调用
   203→    // 步骤 8：加载 initproc（返回 Process + Thread）
   204→    let initproc = read_all(FS.open("initproc", OpenFlags::RDONLY).unwrap());
   205→    if let Some((process, thread)) = Process::from_elf(ElfFile::new(initproc.as_slice()).unwrap()) {
   206→        // 初始化双层管理器：ProcManager（进程）+ ThreadManager（线程）
   207→        PROCESSOR.get_mut().set_proc_manager(ProcManager::new());
   208→        PROCESSOR.get_mut().set_manager(ThreadManager::new());
   209→        let (pid, tid) = (process.pid, thread.tid);
   210→        PROCESSOR
   211→            .get_mut()
   212→            .add_proc(pid, process, ProcId::from_usize(usize::MAX));
   213→        PROCESSOR.get_mut().add(tid, thread, pid);
   214→    }
   215→
   216→    // ─── 主调度循环 ───
   217→    loop {
   218→        let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   219→        if let Some(task) = unsafe { (*processor).find_next() } {
   220→            unsafe { task.context.execute(portal, ()) };
   221→
   222→            match scause::read().cause() {
   223→                // ─── 系统调用 ───
   224→                scause::Trap::Exception(scause::Exception::UserEnvCall) => {
   225→                    use tg_syscall::{SyscallId as Id, SyscallResult as Ret};
   226→                    let ctx = &mut task.context.context;
   227→                    ctx.move_next();
   228→                    let id: Id = ctx.a(7).into();
   229→                    let args = [ctx.a(0), ctx.a(1), ctx.a(2), ctx.a(3), ctx.a(4), ctx.a(5)];
   230→                    let syscall_ret = tg_syscall::handle(Caller { entity: 0, flow: 0 }, id, args);
   231→
   232→                    // ─── 信号处理 ───
   233→                    let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   234→                    match current_proc.signal.handle_signals(ctx) {
   235→                        SignalResult::ProcessKilled(exit_code) => unsafe {
   236→                            (*processor).make_current_exited(exit_code as _)
   237→                        },
   238→                        _ => match syscall_ret {
   239→                            Ret::Done(ret) => match id {
   240→                                Id::EXIT => unsafe { (*processor).make_current_exited(ret) },
   241→                                // ─── 本章新增：同步原语阻塞处理 ───
   242→                                // 当 semaphore_down / mutex_lock / condvar_wait 返回 -1 时，
   243→                                // 表示资源不可用，将当前线程标记为阻塞态
   244→                                Id::SEMAPHORE_DOWN | Id::MUTEX_LOCK | Id::CONDVAR_WAIT => {
   245→                                    let ctx = &mut task.context.context;
   246→                                    *ctx.a_mut(0) = ret as _;
   247→                                    if ret == -1 {
   248→                                        // 阻塞：从就绪队列移除，等待资源释放后唤醒
   249→                                        unsafe { (*processor).make_current_blocked() };
   250→                                    } else {
   251→                                        // 成功获取：正常挂起（时间片轮转）
   252→                                        unsafe { (*processor).make_current_suspend() };
   253→                                    }
   254→                                }
   255→                                _ => {
   256→                                    let ctx = &mut task.context.context;
   257→                                    *ctx.a_mut(0) = ret as _;
   258→                                    unsafe { (*processor).make_current_suspend() };
   259→                                }
   260→                            },
   261→                            Ret::Unsupported(_) => {
   262→                                log::info!("id = {id:?}");
   263→                                unsafe { (*processor).make_current_exited(-2) };
   264→                            }
   265→                        },
   266→                    }
   267→                }
   268→                e => {
   269→                    log::error!("unsupported trap: {e:?}");
   270→                    unsafe { (*processor).make_current_exited(-3) };
   271→                }
   272→            }
   273→        } else {
   274→            println!("no task");
   275→            break;
   276→        }
   277→    }
   278→
   279→    tg_sbi::shutdown(false)
   280→}
