   289→/// 建立内核地址空间（与前几章相同）
   290→fn kernel_space(layout: tg_linker::KernelLayout, memory: usize, portal: usize) {
   291→    let mut space = AddressSpace::new();
   292→    for region in layout.iter() {
   293→        log::info!("{region}");
   294→        use tg_linker::KernelRegionTitle::*;
   295→        let flags = match region.title {
   296→            Text => "X_RV",
   297→            Rodata => "__RV",
   298→            Data | Boot => "_WRV",
   299→        };
   300→        let s = VAddr::<Sv39>::new(region.range.start);
   301→        let e = VAddr::<Sv39>::new(region.range.end);
   302→        space.map_extern(
   303→            s.floor()..e.ceil(),
   304→            PPN::new(s.floor().val()),
   305→            build_flags(flags),
   306→        )
   307→    }
   308→    let s = VAddr::<Sv39>::new(layout.end());
   309→    let e = VAddr::<Sv39>::new(layout.start() + memory);
   310→    log::info!("(heap) ---> {:#10x}..{:#10x}", s.val(), e.val());
   311→    space.map_extern(
   312→        s.floor()..e.ceil(),
   313→        PPN::new(s.floor().val()),
   314→        build_flags("_WRV"),
   315→    );
   316→    space.map_extern(
   317→        PROTAL_TRANSIT..PROTAL_TRANSIT + 1,
   318→        PPN::new(portal >> Sv39::PAGE_BITS),
   319→        build_flags("__G_XWRV"),
   320→    );
   321→    println!();
   322→    for (base, len) in MMIO {
   323→        let s = VAddr::<Sv39>::new(*base);
   324→        let e = VAddr::<Sv39>::new(*base + *len);
   325→        log::info!("MMIO range -> {:#10x}..{:#10x}", s.val(), e.val());
   326→        space.map_extern(
   327→            s.floor()..e.ceil(),
   328→            PPN::new(s.floor().val()),
   329→            build_flags("_WRV"),
   330→        );
   331→    }
   332→    unsafe { satp::set(satp::Mode::Sv39, 0, space.root_ppn().val()) };
   333→    unsafe { KERNEL_SPACE.write(space) };
   334→}
