   336→/// 将异界传送门映射到用户地址空间
   337→fn map_portal(space: &AddressSpace<Sv39, Sv39Manager>) {
   338→    let portal_idx = PROTAL_TRANSIT.index_in(Sv39::MAX_LEVEL);
   339→    space.root()[portal_idx] = unsafe { KERNEL_SPACE.assume_init_ref() }.root()[portal_idx];
   340→}
