   430→    const READABLE: VmFlags<Sv39> = build_flags("RV");
   431→    const WRITEABLE: VmFlags<Sv39> = build_flags("W_V");
   432→
   433→    /// IO 系统调用（与第七章基本相同）
   434→    ///
   435→    /// 注意：本章通过 `get_current_proc()` 获取当前线程所属的进程，
   436→    /// 而非直接 `current()`，因为 fd_table 属于进程而非线程。
   437→    impl IO for SyscallContext {
   438→        fn write(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
   439→            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
   440→            if let Some(ptr) = current.address_space.translate(VAddr::new(buf), READABLE) {
   441→                if fd == STDOUT || fd == STDDEBUG {
   442→                    print!("{}", unsafe {
   443→                        core::str::from_utf8_unchecked(core::slice::from_raw_parts(
   444→                            ptr.as_ptr(), count,
   445→                        ))
   446→                    });
   447→                    count as _
   448→                } else if let Some(file) = &current.fd_table[fd] {
   449→                    let file = file.lock();
   450→                    if file.writable() {
   451→                        let mut v: Vec<&'static mut [u8]> = Vec::new();
   452→                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
   453→                        file.write(UserBuffer::new(v)) as _
   454→                    } else { log::error!("file not writable"); -1 }
   455→                } else { log::error!("unsupported fd: {fd}"); -1 }
   456→            } else { log::error!("ptr not readable"); -1 }
   457→        }
   458→
   459→        fn read(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
   460→            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
   461→            if let Some(ptr) = current.address_space.translate(VAddr::new(buf), WRITEABLE) {
   462→                if fd == STDIN {
   463→                    let mut ptr = ptr.as_ptr();
   464→                    for _ in 0..count {
   465→                        unsafe { *ptr = tg_sbi::console_getchar() as u8; ptr = ptr.add(1); }
   466→                    }
   467→                    count as _
   468→                } else if let Some(file) = &current.fd_table[fd] {
   469→                    let file = file.lock();
   470→                    if file.readable() {
   471→                        let mut v: Vec<&'static mut [u8]> = Vec::new();
   472→                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
   473→                        file.read(UserBuffer::new(v)) as _
   474→                    } else { log::error!("file not readable"); -1 }
   475→                } else { log::error!("unsupported fd: {fd}"); -1 }
   476→            } else { log::error!("ptr not writeable"); -1 }
   477→        }
   478→
   479→        fn open(&self, _caller: Caller, path: usize, flags: usize) -> isize {
   480→            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
   481→            if let Some(ptr) = current.address_space.translate(VAddr::new(path), READABLE) {
   482→                let mut string = String::new();
   483→                let mut raw_ptr: *mut u8 = ptr.as_ptr();
   484→                loop {
   485→                    unsafe {
   486→                        let ch = *raw_ptr;
   487→                        if ch == 0 { break; }
   488→                        string.push(ch as char);
   489→                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
   490→                    }
   491→                }
   492→                if let Some(file_handle) =
   493→                    FS.open(string.as_str(), OpenFlags::from_bits(flags as u32).unwrap())
   494→                {
   495→                    let new_fd = current.fd_table.len();
   496→                    current.fd_table.push(Some(Mutex::new(Fd::File((*file_handle).clone()))));
   497→                    new_fd as isize
   498→                } else { -1 }
   499→            } else { log::error!("ptr not writeable"); -1 }
   500→        }
   501→
   502→        #[inline]
   503→        fn close(&self, _caller: Caller, fd: usize) -> isize {
   504→            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
   505→            if fd >= current.fd_table.len() || current.fd_table[fd].is_none() { return -1; }
   506→            current.fd_table[fd].take();
   507→            0
   508→        }
   509→
   510→        /// pipe 系统调用
   511→        fn pipe(&self, _caller: Caller, pipe: usize) -> isize {
   512→            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
   513→            let (read_end, write_end) = make_pipe();
   514→            let read_fd = current.fd_table.len();
   515→            let write_fd = read_fd + 1;
   516→            if let Some(mut ptr) = current.address_space
   517→                .translate::<usize>(VAddr::new(pipe), WRITEABLE)
   518→            { unsafe { *ptr.as_mut() = read_fd }; } else { return -1; }
   519→            if let Some(mut ptr) = current.address_space
   520→                .translate::<usize>(VAddr::new(pipe + core::mem::size_of::<usize>()), WRITEABLE)
   521→            { unsafe { *ptr.as_mut() = write_fd }; } else { return -1; }
   522→            current.fd_table.push(Some(Mutex::new(Fd::PipeRead(read_end))));
   523→            current.fd_table.push(Some(Mutex::new(Fd::PipeWrite(write_end))));
   524→            0
   525→        }
   526→    }
   527→
   528→    /// 进程管理系统调用
   529→    impl Process for SyscallContext {
   530→        #[inline]
   531→        fn exit(&self, _caller: Caller, exit_code: usize) -> isize { exit_code as isize }
   532→
   533→        /// fork：创建子进程（返回 Process + Thread）
   534→        fn fork(&self, _caller: Caller) -> isize {
   535→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   536→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   537→            let parent_pid = current_proc.pid;
   538→            let (proc, mut thread) = current_proc.fork().unwrap();
   539→            let pid = proc.pid;
   540→            *thread.context.context.a_mut(0) = 0 as _;
   541→            unsafe {
   542→                (*processor).add_proc(pid, proc, parent_pid);
   543→                (*processor).add(thread.tid, thread, pid);
   544→            }
   545→            pid.get_usize() as isize
   546→        }
   547→
   548→        /// exec：从文件系统加载新程序
   549→        fn exec(&self, _caller: Caller, path: usize, count: usize) -> isize {
   550→            const READABLE: VmFlags<Sv39> = build_flags("RV");
   551→            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
   552→            current.address_space
   553→                .translate(VAddr::new(path), READABLE)
   554→                .map(|ptr| unsafe {
   555→                    core::str::from_utf8_unchecked(core::slice::from_raw_parts(ptr.as_ptr(), count))
   556→                })
   557→                .and_then(|name| FS.open(name, OpenFlags::RDONLY))
   558→                .map_or_else(
   559→                    || {
   560→                        log::error!("unknown app, select one in the list: ");
   561→                        FS.readdir("").unwrap().into_iter().for_each(|app| println!("{app}"));
   562→                        println!();
   563→                        -1
   564→                    },
   565→                    |fd| { current.exec(ElfFile::new(&read_all(fd)).unwrap()); 0 },
   566→                )
   567→        }
   568→
   569→        fn wait(&self, _caller: Caller, pid: isize, exit_code_ptr: usize) -> isize {
   570→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   571→            let current = unsafe { (*processor).get_current_proc().unwrap() };
   572→            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
   573→            if let Some((dead_pid, exit_code)) =
   574→                unsafe { (*processor).wait(ProcId::from_usize(pid as usize)) }
   575→            {
   576→                if let Some(mut ptr) = current.address_space
   577→                    .translate::<i32>(VAddr::new(exit_code_ptr), WRITABLE)
   578→                { unsafe { *ptr.as_mut() = exit_code as i32 }; }
   579→                return dead_pid.get_usize() as isize;
   580→            } else { return -1; }
   581→        }
   582→
   583→        fn getpid(&self, _caller: Caller) -> isize {
   584→            PROCESSOR.get_mut().get_current_proc().unwrap().pid.get_usize() as _
   585→        }
   586→    }
   587→
   588→    impl Scheduling for SyscallContext {
   589→        #[inline]
   590→        fn sched_yield(&self, _caller: Caller) -> isize { 0 }
   591→    }
   592→
   593→    impl Clock for SyscallContext {
   594→        #[inline]
   595→        fn clock_gettime(&self, _caller: Caller, clock_id: ClockId, tp: usize) -> isize {
   596→            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
   597→            match clock_id {
   598→                ClockId::CLOCK_MONOTONIC => {
   599→                    if let Some(mut ptr) = PROCESSOR.get_mut().get_current_proc().unwrap()
   600→                        .address_space.translate(VAddr::new(tp), WRITABLE)
   601→                    {
   602→                        let time = riscv::register::time::read() * 10000 / 125;
   603→                        *unsafe { ptr.as_mut() } = TimeSpec {
   604→                            tv_sec: time / 1_000_000_000,
   605→                            tv_nsec: time % 1_000_000_000,
   606→                        };
   607→                        0
   608→                    } else { log::error!("ptr not readable"); -1 }
   609→                }
   610→                _ => -1,
   611→            }
   612→        }
   613→    }
   614→
   615→    /// 信号系统调用（与第七章相同）
   616→    impl Signal for SyscallContext {
   617→        fn kill(&self, _caller: Caller, pid: isize, signum: u8) -> isize {
   618→            if let Some(target_task) = PROCESSOR.get_mut()
   619→                .get_proc(ProcId::from_usize(pid as usize))
   620→            {
   621→                if let Ok(signal_no) = SignalNo::try_from(signum) {
   622→                    if signal_no != SignalNo::ERR {
   623→                        target_task.signal.add_signal(signal_no);
   624→                        return 0;
   625→                    }
   626→                }
   627→            }
   628→            -1
   629→        }
   630→
   631→        fn sigaction(&self, _caller: Caller, signum: u8, action: usize, old_action: usize) -> isize {
   632→            if signum as usize > tg_signal::MAX_SIG { return -1; }
   633→            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
   634→            if let Ok(signal_no) = SignalNo::try_from(signum) {
   635→                if signal_no == SignalNo::ERR { return -1; }
   636→                if old_action as usize != 0 {
   637→                    if let Some(mut ptr) = current.address_space.translate(VAddr::new(old_action), WRITEABLE) {
   638→                        if let Some(signal_action) = current.signal.get_action_ref(signal_no) {
   639→                            *unsafe { ptr.as_mut() } = signal_action;
   640→                        } else { return -1; }
   641→                    } else { return -1; }
   642→                }
   643→                if action as usize != 0 {
   644→                    if let Some(ptr) = current.address_space.translate(VAddr::new(action), READABLE) {
   645→                        if !current.signal.set_action(signal_no, &unsafe { *ptr.as_ptr() }) { return -1; }
   646→                    } else { return -1; }
   647→                }
   648→                return 0;
   649→            }
   650→            -1
   651→        }
   652→
   653→        fn sigprocmask(&self, _caller: Caller, mask: usize) -> isize {
   654→            PROCESSOR.get_mut().get_current_proc().unwrap().signal.update_mask(mask) as isize
   655→        }
   656→
   657→        fn sigreturn(&self, _caller: Caller) -> isize {
   658→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   659→            let current = unsafe { (*processor).get_current_proc().unwrap() };
   660→            let current_thread = unsafe { (*processor).current().unwrap() };
   661→            if current.signal.sig_return(&mut current_thread.context.context) { 0 } else { -1 }
   662→        }
   663→    }
   664→
   665→    /// 线程系统调用（**本章新增**）
   666→    impl tg_syscall::Thread for SyscallContext {
   667→        /// thread_create：在当前进程中创建新线程
   668→        ///
   669→        /// 为新线程分配独立的用户栈（从高地址向下搜索未映射的页面），
   670→        /// 创建新的执行上下文，入口为 entry，参数为 arg。
   671→        fn thread_create(&self, _caller: Caller, entry: usize, arg: usize) -> isize {
   672→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   673→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   674→            // 从最高用户栈位置向下搜索空闲的页表区域
   675→            let mut vpn = VPN::<Sv39>::new((1 << 26) - 2);
   676→            let addrspace = &mut current_proc.address_space;
   677→            loop {
   678→                let idx = vpn.index_in(Sv39::MAX_LEVEL);
   679→                if !addrspace.root()[idx].is_valid() { break; }
   680→                vpn = VPN::<Sv39>::new(vpn.val() - 3);
   681→            }
   682→            // 分配 2 页用户栈
   683→            let stack = unsafe {
   684→                alloc_zeroed(Layout::from_size_align_unchecked(
   685→                    2 << Sv39::PAGE_BITS, 1 << Sv39::PAGE_BITS,
   686→                ))
   687→            };
   688→            addrspace.map_extern(vpn..vpn + 2, PPN::new(stack as usize >> Sv39::PAGE_BITS), build_flags("U_WRV"));
   689→            let satp = (8 << 60) | addrspace.root_ppn().val();
   690→            let mut context = tg_kernel_context::LocalContext::user(entry);
   691→            *context.sp_mut() = (vpn + 2).base().val();
   692→            *context.a_mut(0) = arg;
   693→            let thread = Thread::new(satp, context);
   694→            let tid = thread.tid;
   695→            unsafe { (*processor).add(tid, thread, current_proc.pid); }
   696→            tid.get_usize() as _
   697→        }
   698→
   699→        /// gettid：获取当前线程 TID
   700→        fn gettid(&self, _caller: Caller) -> isize {
   701→            PROCESSOR.get_mut().current().unwrap().tid.get_usize() as _
   702→        }
   703→
   704→        /// waittid：等待指定线程退出
   705→        fn waittid(&self, _caller: Caller, tid: usize) -> isize {
   706→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   707→            let current_thread = unsafe { (*processor).current().unwrap() };
   708→            if tid == current_thread.tid.get_usize() { return -1; }
   709→            if let Some(exit_code) = unsafe { (*processor).waittid(ThreadId::from_usize(tid)) } {
   710→                exit_code
   711→            } else { -1 }
   712→        }
   713→    }
   714→
   715→    /// 同步原语系统调用（**本章新增**）
   716→    ///
   717→    /// 实现 Mutex、Semaphore、Condvar 的创建和操作。
   718→    /// 这些同步原语存储在 Process 的列表中，由所有线程共享。
   719→    impl SyncMutex for SyscallContext {
   720→        /// 创建信号量（初始计数 = res_count）
   721→        fn semaphore_create(&self, _caller: Caller, res_count: usize) -> isize {
   722→            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
   723→            let id = if let Some(id) = current_proc.semaphore_list.iter().enumerate()
   724→                .find(|(_, item)| item.is_none()).map(|(id, _)| id)
   725→            {
   726→                current_proc.semaphore_list[id] = Some(Arc::new(Semaphore::new(res_count)));
   727→                id
   728→            } else {
   729→                current_proc.semaphore_list.push(Some(Arc::new(Semaphore::new(res_count))));
   730→                current_proc.semaphore_list.len() - 1
   731→            };
   732→            id as isize
   733→        }
   734→
   735→        /// V 操作：释放信号量，唤醒等待线程
   736→        fn semaphore_up(&self, _caller: Caller, sem_id: usize) -> isize {
   737→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   738→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   739→            let sem = Arc::clone(current_proc.semaphore_list[sem_id].as_ref().unwrap());
   740→            if let Some(tid) = sem.up() {
   741→                unsafe { (*processor).re_enque(tid); }
   742→            }
   743→            0
   744→        }
   745→
   746→        /// P 操作：获取信号量，不可用则阻塞
   747→        fn semaphore_down(&self, _caller: Caller, sem_id: usize) -> isize {
   748→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   749→            let current = unsafe { (*processor).current().unwrap() };
   750→            let tid = current.tid;
   751→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   752→            let sem = Arc::clone(current_proc.semaphore_list[sem_id].as_ref().unwrap());
   753→            if !sem.down(tid) { -1 } else { 0 }
   754→        }
   755→
   756→        /// 创建互斥锁（blocking=true 为阻塞锁）
   757→        fn mutex_create(&self, _caller: Caller, blocking: bool) -> isize {
   758→            let new_mutex: Option<Arc<dyn MutexTrait>> = if blocking {
   759→                Some(Arc::new(MutexBlocking::new()))
   760→            } else { None };
   761→            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
   762→            if let Some(id) = current_proc.mutex_list.iter().enumerate()
   763→                .find(|(_, item)| item.is_none()).map(|(id, _)| id)
   764→            {
   765→                current_proc.mutex_list[id] = new_mutex;
   766→                id as isize
   767→            } else {
   768→                current_proc.mutex_list.push(new_mutex);
   769→                current_proc.mutex_list.len() as isize - 1
   770→            }
   771→        }
   772→
   773→        /// 解锁，唤醒等待线程
   774→        fn mutex_unlock(&self, _caller: Caller, mutex_id: usize) -> isize {
   775→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   776→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   777→            let mutex = Arc::clone(current_proc.mutex_list[mutex_id].as_ref().unwrap());
   778→            if let Some(tid) = mutex.unlock() {
   779→                unsafe { (*processor).re_enque(tid); }
   780→            }
   781→            0
   782→        }
   783→
   784→        /// 加锁，已被占用则阻塞
   785→        fn mutex_lock(&self, _caller: Caller, mutex_id: usize) -> isize {
   786→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   787→            let current = unsafe { (*processor).current().unwrap() };
   788→            let tid = current.tid;
   789→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   790→            let mutex = Arc::clone(current_proc.mutex_list[mutex_id].as_ref().unwrap());
   791→            if !mutex.lock(tid) { -1 } else { 0 }
   792→        }
   793→
   794→        /// 创建条件变量
   795→        fn condvar_create(&self, _caller: Caller, _arg: usize) -> isize {
   796→            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
   797→            let id = if let Some(id) = current_proc.condvar_list.iter().enumerate()
   798→                .find(|(_, item)| item.is_none()).map(|(id, _)| id)
   799→            {
   800→                current_proc.condvar_list[id] = Some(Arc::new(Condvar::new()));
   801→                id
   802→            } else {
   803→                current_proc.condvar_list.push(Some(Arc::new(Condvar::new())));
   804→                current_proc.condvar_list.len() - 1
   805→            };
   806→            id as isize
   807→        }
   808→
   809→        /// 唤醒一个等待线程
   810→        fn condvar_signal(&self, _caller: Caller, condvar_id: usize) -> isize {
   811→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   812→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   813→            let condvar = Arc::clone(current_proc.condvar_list[condvar_id].as_ref().unwrap());
   814→            if let Some(tid) = condvar.signal() {
   815→                unsafe { (*processor).re_enque(tid); }
   816→            }
   817→            0
   818→        }
   819→
   820→        /// 等待条件变量（释放锁 + 阻塞 + 重新获取锁）
   821→        fn condvar_wait(&self, _caller: Caller, condvar_id: usize, mutex_id: usize) -> isize {
   822→            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   823→            let current = unsafe { (*processor).current().unwrap() };
   824→            let tid = current.tid;
   825→            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
   826→            let condvar = Arc::clone(current_proc.condvar_list[condvar_id].as_ref().unwrap());
   827→            let mutex = Arc::clone(current_proc.mutex_list[mutex_id].as_ref().unwrap());
   828→            let (flag, waking_tid) = condvar.wait_with_mutex(tid, mutex);
   829→            if let Some(waking_tid) = waking_tid {
   830→                unsafe { (*processor).re_enque(waking_tid); }
   831→            }
   832→            if !flag { -1 } else { 0 }
   833→        }
   834→
   835→        /// 死锁检测（TODO 练习题）
   836→        fn enable_deadlock_detect(&self, _caller: Caller, is_enable: i32) -> isize {
   837→            tg_console::log::info!("enable_deadlock_detect: is_enable = {is_enable}, not implemented");
   838→            -1
   839→        }
   840→    }
   841→}
   842→
   843→/// 非 RISC-V64 架构的占位实现
   844→#[cfg(not(target_arch = "riscv64"))]
   845→mod stub {
   846→    use tg_kernel_vm::page_table::{MmuMeta, VmFlags};
   847→
   848→    /// Sv39 占位类型
   849→    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
   850→    pub struct Sv39;
   851→    impl MmuMeta for Sv39 {
   852→        const P_ADDR_BITS: usize = 56;
   853→        const PAGE_BITS: usize = 12;
   854→        const LEVEL_BITS: &'static [usize] = &[9, 9, 9];
   855→        const PPN_POS: usize = 10;
   856→        #[inline]
   857→        fn is_leaf(value: usize) -> bool { value & 0b1110 != 0 }
   858→    }
   859→    /// 构建 VmFlags 占位
   860→    pub const fn build_flags(_s: &str) -> VmFlags<Sv39> { unsafe { VmFlags::from_raw(0) } }
   861→    /// 解析 VmFlags 占位
   862→    pub fn parse_flags(_s: &str) -> Result<VmFlags<Sv39>, ()> { Ok(unsafe { VmFlags::from_raw(0) }) }
   863→
   864→    #[unsafe(no_mangle)]
   865→    pub extern "C" fn main() -> i32 { 0 }
   866→    #[unsafe(no_mangle)]
   867→    pub extern "C" fn __libc_start_main() -> i32 { 0 }
   868→    #[unsafe(no_mangle)]
   869→    pub extern "C" fn rust_eh_personality() {}
   870→}
