     1→//! 进程与线程管理模块
     2→//!
     3→//! ## 与第七章的区别
     4→//!
     5→//! 第七章中 `Process` 既是资源容器又是执行单元。
     6→//! 第八章将两者分离：
     7→//! - **Process**：资源容器，管理地址空间、文件描述符、**同步原语列表**、信号
     8→//! - **Thread**：执行单元，管理 TID 和上下文
     9→//!
    10→//! 同一进程的所有线程共享 `Process` 中的资源。
    11→//!
    12→//! ## 新增字段
    13→//!
    14→//! | 字段 | 说明 |
    15→//! |------|------|
    16→//! | `semaphore_list` | 信号量列表（进程内所有线程共享） |
    17→//! | `mutex_list` | 互斥锁列表 |
    18→//! | `condvar_list` | 条件变量列表 |
    19→//!
    20→//! 教程阅读建议：
    21→//!
    22→//! - 先看 `Process` 与 `Thread` 的字段分工：明确“资源归进程、执行归线程”；
    23→//! - 再看 `fork/exec/from_elf`：理解跨线程模型后，进程复制与替换语义如何变化；
    24→//! - 最后结合 `processor.rs` 看线程生命周期与进程资源回收的关系。
    25→
    26→use crate::{
    27→    build_flags, fs::Fd, map_portal, parse_flags, processor::ProcessorInner, Sv39, Sv39Manager,
    28→    PROCESSOR,
    29→};
    30→use alloc::{alloc::alloc_zeroed, boxed::Box, sync::Arc, vec::Vec};
    31→use core::alloc::Layout;
    32→use spin::Mutex;
    33→use tg_kernel_context::{foreign::ForeignContext, LocalContext};
    34→use tg_kernel_vm::{
    35→    page_table::{MmuMeta, VAddr, PPN, VPN},
    36→    AddressSpace,
    37→};
    38→use tg_signal::Signal;
    39→use tg_signal_impl::SignalImpl;
    40→use tg_sync::{Condvar, Mutex as MutexTrait, Semaphore};
    41→use tg_task_manage::{ProcId, ThreadId};
    42→use xmas_elf::{
    43→    header::{self, HeaderPt2, Machine},
    44→    program, ElfFile,
    45→};
    46→
    47→/// 线程（执行单元）
    48→///
    49→/// 每个线程有独立的 TID 和上下文（寄存器状态、satp）。
    50→/// 同一进程的多个线程共享地址空间。
    51→pub struct Thread {
    52→    /// 线程 ID（不可变）
    53→    pub tid: ThreadId,
    54→    /// 执行上下文（包含 LocalContext + satp）
    55→    pub context: ForeignContext,
    56→}
    57→
    58→impl Thread {
    59→    /// 创建新线程
    60→    pub fn new(satp: usize, context: LocalContext) -> Self {
    61→        Self {
    62→            tid: ThreadId::new(),
    63→            context: ForeignContext { context, satp },
    64→        }
    65→    }
    66→}
    67→
    68→/// 进程（资源容器）
    69→///
    70→/// 管理地址空间、文件描述符、同步原语、信号等共享资源。
    71→/// 一个进程可以包含多个线程。
    72→pub struct Process {
    73→    /// 进程 ID
    74→    pub pid: ProcId,
    75→    /// 地址空间（所有线程共享）
    76→    pub address_space: AddressSpace<Sv39, Sv39Manager>,
    77→    /// 文件描述符表（所有线程共享）
    78→    pub fd_table: Vec<Option<Mutex<Fd>>>,
    79→    /// 信号处理器
    80→    pub signal: Box<dyn Signal>,
    81→    /// 信号量列表（**本章新增**，所有线程共享）
    82→    pub semaphore_list: Vec<Option<Arc<Semaphore>>>,
    83→    /// 互斥锁列表（**本章新增**，所有线程共享）
    84→    pub mutex_list: Vec<Option<Arc<dyn MutexTrait>>>,
    85→    /// 条件变量列表（**本章新增**，所有线程共享）
    86→    pub condvar_list: Vec<Option<Arc<Condvar>>>,
    87→}
    88→
    89→impl Process {
    90→    /// exec：替换当前进程的地址空间和主线程上下文
    91→    ///
    92→    /// 注意：只支持单线程进程执行 exec
    93→    pub fn exec(&mut self, elf: ElfFile) {
    94→        let (proc, thread) = Process::from_elf(elf).unwrap();
    95→        self.address_space = proc.address_space;
    96→        let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
    97→        unsafe {
    98→            let pthreads = (*processor).get_thread(self.pid).unwrap();
    99→            (*processor).get_task(pthreads[0]).unwrap().context = thread.context;
   100→        }
   101→    }
   102→
   103→    /// fork：创建子进程（复制地址空间和主线程上下文）
   104→    ///
   105→    /// 子进程继承父进程的地址空间（深拷贝）、文件描述符和信号配置。
   106→    /// 同步原语列表不继承（子进程创建空的列表）。
   107→    pub fn fork(&mut self) -> Option<(Self, Thread)> {
   108→        let pid = ProcId::new();
   109→        // 深拷贝地址空间
   110→        let parent_addr_space = &self.address_space;
   111→        let mut address_space: AddressSpace<Sv39, Sv39Manager> = AddressSpace::new();
   112→        parent_addr_space.cloneself(&mut address_space);
   113→        map_portal(&address_space);
   114→        // 复制主线程上下文
   115→        let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
   116→        let pthreads = unsafe { (*processor).get_thread(self.pid).unwrap() };
   117→        let context = unsafe {
   118→            (*processor).get_task(pthreads[0]).unwrap().context.context.clone()
   119→        };
   120→        let satp = (8 << 60) | address_space.root_ppn().val();
   121→        let thread = Thread::new(satp, context);
   122→        // 复制文件描述符表
   123→        let new_fd_table: Vec<Option<Mutex<Fd>>> = self.fd_table
   124→            .iter()
   125→            .map(|fd| fd.as_ref().map(|f| Mutex::new(f.lock().clone())))
   126→            .collect();
   127→        Some((
   128→            Self {
   129→                pid,
   130→                address_space,
   131→                fd_table: new_fd_table,
   132→                signal: self.signal.from_fork(),
   133→                // 子进程的同步原语列表初始为空
   134→                semaphore_list: Vec::new(),
   135→                mutex_list: Vec::new(),
   136→                condvar_list: Vec::new(),
   137→            },
   138→            thread,
   139→        ))
   140→    }
   141→
   142→    /// 从 ELF 文件创建进程和主线程
   143→    ///
   144→    /// 解析 ELF 段，建立地址空间，分配用户栈，创建初始上下文。
   145→    pub fn from_elf(elf: ElfFile) -> Option<(Self, Thread)> {
   146→        let entry = match elf.header.pt2 {
   147→            HeaderPt2::Header64(pt2)
   148→                if pt2.type_.as_type() == header::Type::Executable
   149→                    && pt2.machine.as_machine() == Machine::RISC_V =>
   150→            { pt2.entry_point as usize }
   151→            _ => None?,
   152→        };
   153→
   154→        const PAGE_SIZE: usize = 1 << Sv39::PAGE_BITS;
   155→        const PAGE_MASK: usize = PAGE_SIZE - 1;
   156→
   157→        let mut address_space = AddressSpace::new();
   158→        for program in elf.program_iter() {
   159→            if !matches!(program.get_type(), Ok(program::Type::Load)) { continue; }
   160→            let off_file = program.offset() as usize;
   161→            let len_file = program.file_size() as usize;
   162→            let off_mem = program.virtual_addr() as usize;
   163→            let end_mem = off_mem + program.mem_size() as usize;
   164→            assert_eq!(off_file & PAGE_MASK, off_mem & PAGE_MASK);
   165→            let mut flags: [u8; 5] = *b"U___V";
   166→            if program.flags().is_execute() { flags[1] = b'X'; }
   167→            if program.flags().is_write() { flags[2] = b'W'; }
   168→            if program.flags().is_read() { flags[3] = b'R'; }
   169→            address_space.map(
   170→                VAddr::new(off_mem).floor()..VAddr::new(end_mem).ceil(),
   171→                &elf.input[off_file..][..len_file],
   172→                off_mem & PAGE_MASK,
   173→                parse_flags(unsafe { core::str::from_utf8_unchecked(&flags) }).unwrap(),
   174→            );
   175→        }
   176→        // 分配 2 页用户栈
   177→        let stack = unsafe {
   178→            alloc_zeroed(Layout::from_size_align_unchecked(
   179→                2 << Sv39::PAGE_BITS, 1 << Sv39::PAGE_BITS,
   180→            ))
   181→        };
   182→        address_space.map_extern(
   183→            VPN::new((1 << 26) - 2)..VPN::new(1 << 26),
   184→            PPN::new(stack as usize >> Sv39::PAGE_BITS),
   185→            build_flags("U_WRV"),
   186→        );
   187→        map_portal(&address_space);
   188→        let satp = (8 << 60) | address_space.root_ppn().val();
   189→        let mut context = LocalContext::user(entry);
   190→        *context.sp_mut() = 1 << 38;
   191→        let thread = Thread::new(satp, context);
   192→
   193→        Some((
   194→            Self {
   195→                pid: ProcId::new(),
   196→                address_space,
   197→                fd_table: vec![
