     1→//! # 第六章：文件系统
     2→//!
     3→//! 本章在第五章"进程管理"的基础上，引入了 **文件系统** 支持。
     4→//! 用户程序不再嵌入内核镜像，而是存放在 **磁盘镜像**（fs.img）中，
     5→//! 内核通过 **VirtIO 块设备驱动** 和 **easy-fs 文件系统** 按名称加载和执行程序。
     6→//!
     7→//! ## 核心概念
     8→//!
     9→//! - **文件系统（easy-fs）**：简单的类 UNIX inode 文件系统，支持单级目录
    10→//! - **块设备驱动（VirtIO-blk）**：通过 MMIO 访问虚拟块设备
    11→//! - **文件描述符表**：每个进程维护 fd_table，统一管理标准 I/O 和普通文件
    12→//! - **文件操作系统调用**：open、close、read、write
    13→//!
    14→//! ## 与第五章的区别
    15→//!
    16→//! | 特性 | 第五章 | 第六章 |
    17→//! |------|--------|--------|
    18→//! | 程序存储 | 嵌入内核镜像（APP_ASM） | 磁盘镜像（fs.img） |
    19→//! | 程序加载 | 按名称查内存表 | 通过文件系统 open + read |
    20→//! | I/O 方式 | 仅 SBI 控制台 | 文件描述符表 + 文件句柄 |
    21→//! | 块设备 | 无 | VirtIO-blk 驱动 |
    22→//! | QEMU 参数 | 无磁盘 | 挂载 fs.img 块设备 |
    23→//!
    24→//! 教程阅读建议：
    25→//!
    26→//! - 先看 `rust_main`：掌握“内核初始化 -> 文件系统启动 -> initproc 加载”的主线；
    27→//! - 再看 `kernel_space`：理解 MMIO 与普通内存映射的差异；
    28→//! - 最后看 `impls`：理解系统调用如何经由 fd_table 访问文件系统。
    29→
    30→// 不使用标准库，裸机环境没有操作系统提供系统调用支持
    31→#![no_std]
    32→// 不使用默认的 main 函数入口，裸机环境需要自定义入口点
    33→#![no_main]
    34→// 在 RISC-V 架构上启用严格的编译警告和文档要求
    35→#![cfg_attr(target_arch = "riscv64", deny(warnings, missing_docs))]
    36→// 在非 RISC-V 架构上允许未使用的代码（用于 IDE 开发体验）
    37→#![cfg_attr(not(target_arch = "riscv64"), allow(dead_code, unused_imports))]
    38→
    39→/// 文件系统模块：easy-fs 文件系统管理器
    40→mod fs;
    41→/// 进程模块：定义 Process 结构体（含文件描述符表）
    42→mod process;
    43→/// 处理器模块：定义 PROCESSOR 全局变量和进程管理器
    44→mod processor;
    45→/// VirtIO 块设备驱动模块
    46→mod virtio_block;
    47→
    48→#[macro_use]
    49→extern crate tg_console;
    50→
    51→#[macro_use]
    52→extern crate alloc;
    53→
    54→use crate::{
    55→    fs::{read_all, FS},
    56→    impls::{Console, Sv39Manager, SyscallContext},
    57→    process::Process,
    58→    processor::ProcManager,
    59→};
    60→use alloc::alloc::alloc;
    61→use core::{alloc::Layout, cell::UnsafeCell, mem::MaybeUninit};
    62→use processor::PROCESSOR;
    63→use riscv::register::*;
    64→#[cfg(not(target_arch = "riscv64"))]
    65→use stub::Sv39;
    66→use tg_console::log;
    67→use tg_easy_fs::{FSManager, OpenFlags};
    68→use tg_kernel_context::foreign::MultislotPortal;
    69→#[cfg(target_arch = "riscv64")]
    70→use tg_kernel_vm::page_table::Sv39;
    71→use tg_kernel_vm::{
    72→    page_table::{MmuMeta, VAddr, VmFlags, VmMeta, PPN, VPN},
    73→    AddressSpace,
    74→};
    75→use tg_sbi;
    76→use tg_syscall::Caller;
    77→use tg_task_manage::{PManager, ProcId};
    78→use xmas_elf::ElfFile;
    79→
    80→/// 构建 VmFlags（虚拟内存标志位）。
    81→#[cfg(target_arch = "riscv64")]
    82→const fn build_flags(s: &str) -> VmFlags<Sv39> {
    83→    VmFlags::build_from_str(s)
    84→}
    85→
    86→/// 运行时解析 VmFlags 字符串。
    87→#[cfg(target_arch = "riscv64")]
    88→fn parse_flags(s: &str) -> Result<VmFlags<Sv39>, ()> {
    89→    s.parse()
    90→}
    91→
    92→#[cfg(not(target_arch = "riscv64"))]
    93→use stub::{build_flags, parse_flags};
    94→
    95→// 定义内核入口点，设置启动栈大小为 32 页 = 128 KiB。
    96→//
    97→// 这里不再调用 tg_linker::boot0! 宏，避免外部已发布版本与 Rust 2024
    98→// 在属性语义上的兼容差异影响本 crate 的发布校验。
    99→#[cfg(target_arch = "riscv64")]
   100→#[unsafe(naked)]
   101→#[unsafe(no_mangle)]
   102→#[unsafe(link_section = ".text.entry")]
   103→unsafe extern "C" fn _start() -> ! {
   104→    const STACK_SIZE: usize = 32 * 4096;
   105→    #[unsafe(link_section = ".boot.stack")]
   106→    static mut STACK: [u8; STACK_SIZE] = [0u8; STACK_SIZE];
   107→
   108→    core::arch::naked_asm!(
   109→        "la sp, {stack} + {stack_size}",
   110→        "j  {main}",
   111→        stack = sym STACK,
   112→        stack_size = const STACK_SIZE,
   113→        main = sym rust_main,
   114→    )
   115→}
   116→
   117→/// 物理内存容量 = 48 MiB
   118→const MEMORY: usize = 48 << 20;
   119→
   120→/// 异界传送门所在虚页（虚拟地址空间最高页）
   121→const PROTAL_TRANSIT: VPN<Sv39> = VPN::MAX;
   122→
   123→/// 内核地址空间的全局存储（延迟初始化）
   124→struct KernelSpace {
   125→    inner: UnsafeCell<MaybeUninit<AddressSpace<Sv39, Sv39Manager>>>,
   126→}
   127→
   128→unsafe impl Sync for KernelSpace {}
   129→
   130→impl KernelSpace {
   131→    const fn new() -> Self {
   132→        Self {
   133→            inner: UnsafeCell::new(MaybeUninit::uninit()),
   134→        }
   135→    }
   136→
   137→    /// 写入内核地址空间（仅在初始化时调用一次）
   138→    unsafe fn write(&self, space: AddressSpace<Sv39, Sv39Manager>) {
   139→        unsafe { *self.inner.get() = MaybeUninit::new(space) };
   140→    }
   141→
   142→    /// 获取内核地址空间的不可变引用
   143→    unsafe fn assume_init_ref(&self) -> &AddressSpace<Sv39, Sv39Manager> {
   144→        unsafe { &*(*self.inner.get()).as_ptr() }
   145→    }
   146→}
   147→
   148→/// 内核地址空间全局实例
   149→static KERNEL_SPACE: KernelSpace = KernelSpace::new();
   150→
   151→/// VirtIO MMIO 设备地址范围
   152→///
   153→/// QEMU virt 平台上 VirtIO 块设备的 MMIO 基地址为 0x1000_1000，大小 0x1000。
   154→/// 需要在内核地址空间中进行恒等映射，以便驱动程序访问。
   155→pub const MMIO: &[(usize, usize)] = &[(0x1000_1000, 0x00_1000)];
