   261→/// 建立内核地址空间
   262→///
   263→/// 内核使用**恒等映射**（Identity Mapping）：虚拟地址 == 物理地址。
   264→///
   265→/// 与第五章相比，本章新增了 **MMIO 映射**，用于访问 VirtIO 块设备。
   266→///
   267→/// 映射内容：
   268→/// 1. 内核代码段、数据段（恒等映射）
   269→/// 2. 堆区域（恒等映射）
   270→/// 3. 异界传送门页面
   271→/// 4. VirtIO MMIO 设备地址（0x10001000，恒等映射）
   272→fn kernel_space(layout: tg_linker::KernelLayout, memory: usize, portal: usize) {
   273→    let mut space = AddressSpace::new();
   274→    // 映射内核各段（恒等映射：VPN == PPN）
   275→    for region in layout.iter() {
   276→        log::info!("{region}");
   277→        use tg_linker::KernelRegionTitle::*;
   278→        let flags = match region.title {
   279→            Text => "X_RV",       // 代码段：可执行、可读
   280→            Rodata => "__RV",     // 只读数据：可读
   281→            Data | Boot => "_WRV", // 数据段：可写、可读
   282→        };
   283→        let s = VAddr::<Sv39>::new(region.range.start);
   284→        let e = VAddr::<Sv39>::new(region.range.end);
   285→        space.map_extern(
   286→            s.floor()..e.ceil(),
   287→            PPN::new(s.floor().val()),
   288→            build_flags(flags),
   289→        )
   290→    }
   291→    // 映射堆区域
   292→    let s = VAddr::<Sv39>::new(layout.end());
   293→    let e = VAddr::<Sv39>::new(layout.start() + memory);
   294→    log::info!("(heap) ---> {:#10x}..{:#10x}", s.val(), e.val());
   295→    space.map_extern(
   296→        s.floor()..e.ceil(),
   297→        PPN::new(s.floor().val()),
   298→        build_flags("_WRV"),
   299→    );
   300→    // 映射异界传送门页面
   301→    space.map_extern(
   302→        PROTAL_TRANSIT..PROTAL_TRANSIT + 1,
   303→        PPN::new(portal >> Sv39::PAGE_BITS),
   304→        build_flags("__G_XWRV"),
   305→    );
   306→    println!();
   307→
   308→    // 映射 VirtIO MMIO 设备地址（恒等映射）
   309→    // 这是本章新增的：VirtIO 块设备通过 MMIO 方式访问
   310→    for (base, len) in MMIO {
   311→        let s = VAddr::<Sv39>::new(*base);
   312→        let e = VAddr::<Sv39>::new(*base + *len);
   313→        log::info!("MMIO range -> {:#10x}..{:#10x}", s.val(), e.val());
   314→        space.map_extern(
   315→            s.floor()..e.ceil(),
   316→            PPN::new(s.floor().val()),
   317→            build_flags("_WRV"),
   318→        );
   319→    }
   320→
   321→    // 激活 Sv39 分页模式
   322→    unsafe { satp::set(satp::Mode::Sv39, 0, space.root_ppn().val()) };
   323→    // 保存内核地址空间到全局变量
   324→    unsafe { KERNEL_SPACE.write(space) };
   325→}
   326→
   327→/// 将内核地址空间中的异界传送门页表项复制到用户地址空间
   328→fn map_portal(space: &AddressSpace<Sv39, Sv39Manager>) {
   329→    let portal_idx = PROTAL_TRANSIT.index_in(Sv39::MAX_LEVEL);
   330→    space.root()[portal_idx] = unsafe { KERNEL_SPACE.assume_init_ref() }.root()[portal_idx];
   331→}
