   368→    pub struct Sv39Manager(NonNull<Pte<Sv39>>);
   369→
   370→    impl Sv39Manager {
   371→        /// 自定义标志位：标记此页面由内核分配
   372→        const OWNED: VmFlags<Sv39> = unsafe { VmFlags::from_raw(1 << 8) };
   373→
   374→        /// 分配对齐的物理页面（已清零）
   375→        #[inline]
   376→        fn page_alloc<T>(count: usize) -> *mut T {
