   378→                alloc_zeroed(Layout::from_size_align_unchecked(
   379→                    count << Sv39::PAGE_BITS,
   380→                    1 << Sv39::PAGE_BITS,
   381→                ))
   382→            }
   383→            .cast()
   384→        }
   385→    }
