   403→        }
   404→        #[inline]
   405→        fn v_to_p<T>(&self, ptr: NonNull<T>) -> PPN<Sv39> {
   406→            PPN::new(VAddr::<Sv39>::new(ptr.as_ptr() as _).floor().val())
   407→        }
   408→        #[inline]
   409→        fn check_owned(&self, pte: Pte<Sv39>) -> bool {
   410→            pte.flags().contains(Self::OWNED)
   411→        }
   412→        #[inline]
   413→        fn allocate(&mut self, len: usize, flags: &mut VmFlags<Sv39>) -> NonNull<u8> {
   414→            *flags |= Self::OWNED;
   415→            NonNull::new(Self::page_alloc(len)).unwrap()
