   437→    // ─── 系统调用实现 ───
   438→
   439→    /// 系统调用上下文
   440→    pub struct SyscallContext;
   441→
   442→    /// 可读权限标志（用于地址翻译时的权限检查）
   443→    const READABLE: VmFlags<Sv39> = build_flags("RV");
   444→    /// 可写权限标志
   445→    const WRITEABLE: VmFlags<Sv39> = build_flags("W_V");
   446→
   447→    /// IO 系统调用实现：read、write、open、close
   448→    ///
   449→    /// 与第五章的关键区别：
   450→    /// - read/write 不仅支持标准 I/O，还支持通过文件描述符读写文件
   451→    /// - 新增 open/close 系统调用，通过 easy-fs 打开磁盘上的文件
   452→    impl IO for SyscallContext {
   453→        /// write 系统调用：写入文件或标准输出
   454→        ///
   455→        /// - fd == STDOUT/STDDEBUG：直接通过控制台输出
   456→        /// - 其他 fd：通过文件描述符表查找文件句柄，写入文件
   457→        fn write(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
   458→            let current = PROCESSOR.get_mut().current().unwrap();
   459→            if let Some(ptr) = current
   460→                .address_space
   461→                .translate::<u8>(VAddr::new(buf), READABLE)
   462→            {
   463→                if fd == STDOUT || fd == STDDEBUG {
   464→                    // 标准输出：直接打印到控制台
   465→                    print!("{}", unsafe {
   466→                        core::str::from_utf8_unchecked(core::slice::from_raw_parts(
   467→                            ptr.as_ptr(),
   468→                            count,
   469→                        ))
   470→                    });
   471→                    count as _
   472→                } else if let Some(file) = &current.fd_table[fd] {
   473→                    // 普通文件：通过文件句柄写入
   474→                    let file = file.lock();
   475→                    if file.writable() {
   476→                        let mut v: Vec<&'static mut [u8]> = Vec::new();
   477→                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
   478→                        file.write(UserBuffer::new(v)) as _
   479→                    } else {
   480→                        log::error!("file not writable");
   481→                        -1
   482→                    }
   483→                } else {
   484→                    log::error!("unsupported fd: {fd}");
   485→                    -1
   486→                }
   487→            } else {
   488→                log::error!("ptr not readable");
   489→                -1
   490→            }
   491→        }
   492→
   493→        /// read 系统调用：从文件或标准输入读取
   494→        ///
   495→        /// - fd == STDIN：通过 SBI console_getchar 逐字符读取
   496→        /// - 其他 fd：通过文件句柄从磁盘文件读取
   497→        fn read(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
   498→            let current = PROCESSOR.get_mut().current().unwrap();
   499→            if let Some(ptr) = current
   500→                .address_space
   501→                .translate::<u8>(VAddr::new(buf), WRITEABLE)
   502→            {
   503→                if fd == STDIN {
   504→                    // 标准输入：通过 SBI 逐字符读取
   505→                    let mut ptr = ptr.as_ptr();
   506→                    for _ in 0..count {
   507→                        unsafe {
   508→                            *ptr = tg_sbi::console_getchar() as u8;
   509→                            ptr = ptr.add(1);
   510→                        }
   511→                    }
   512→                    count as _
   513→                } else if let Some(file) = &current.fd_table[fd] {
   514→                    // 普通文件：通过文件句柄读取
   515→                    let file = file.lock();
   516→                    if file.readable() {
   517→                        let mut v: Vec<&'static mut [u8]> = Vec::new();
   518→                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
   519→                        file.read(UserBuffer::new(v)) as _
   520→                    } else {
   521→                        log::error!("file not readable");
   522→                        -1
   523→                    }
   524→                } else {
   525→                    log::error!("unsupported fd: {fd}");
   526→                    -1
   527→                }
   528→            } else {
   529→                log::error!("ptr not writeable");
   530→                -1
   531→            }
   532→        }
   533→
   534→        /// open 系统调用：打开文件
   535→        ///
   536→        /// 从用户空间读取文件路径（以 '\0' 结尾的字符串），
   537→        /// 通过 easy-fs 文件系统打开文件，分配新的文件描述符。
   538→        fn open(&self, _caller: Caller, path: usize, flags: usize) -> isize {
   539→            let current = PROCESSOR.get_mut().current().unwrap();
   540→            if let Some(ptr) = current.address_space.translate(VAddr::new(path), READABLE) {
   541→                // 从用户空间逐字符读取文件路径（需要地址翻译）
   542→                let mut string = String::new();
   543→                let mut raw_ptr: *mut u8 = ptr.as_ptr();
   544→                loop {
   545→                    unsafe {
   546→                        let ch = *raw_ptr;
   547→                        if ch == 0 {
   548→                            break;
   549→                        }
   550→                        string.push(ch as char);
   551→                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
   552→                    }
   553→                }
   554→
   555→                // 通过文件系统打开文件，分配新的文件描述符
   556→                if let Some(fd) =
   557→                    FS.open(string.as_str(), OpenFlags::from_bits(flags as u32).unwrap())
   558→                {
   559→                    let new_fd = current.fd_table.len();
   560→                    current.fd_table.push(Some(Mutex::new(fd.as_ref().clone())));
   561→                    new_fd as isize
   562→                } else {
   563→                    -1
   564→                }
   565→            } else {
   566→                log::error!("ptr not writeable");
   567→                -1
   568→            }
   569→        }
   570→
   571→        /// close 系统调用：关闭文件描述符
   572→        #[inline]
   573→        fn close(&self, _caller: Caller, fd: usize) -> isize {
   574→            let current = PROCESSOR.get_mut().current().unwrap();
   575→            if fd >= current.fd_table.len() || current.fd_table[fd].is_none() {
   576→                return -1;
   577→            }
   578→            current.fd_table[fd].take();
   579→            0
   580→        }
   581→
   582→        /// linkat 系统调用：创建硬链接
   583→        ///
   584→        /// TODO: 实现 linkat 系统调用（练习题）
   585→        fn linkat(
   586→            &self,
   587→            _caller: Caller,
   588→            _olddirfd: i32,
   589→            oldpath: usize,
   590→            _newdirfd: i32,
   591→            newpath: usize,
   592→            _flags: u32,
   593→        ) -> isize {
   594→            let current = PROCESSOR.get_mut().current().unwrap();
   595→            const READABLE: VmFlags<Sv39> = build_flags("RV");
   596→
   597→            let mut old_string = String::new();
   598→            if let Some(ptr) = current.address_space.translate(VAddr::new(oldpath), READABLE) {
   599→                let mut raw_ptr: *mut u8 = ptr.as_ptr();
   600→                loop {
   601→                    unsafe {
   602→                        let ch = *raw_ptr;
   603→                        if ch == 0 { break; }
   604→                        old_string.push(ch as char);
   605→                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
   606→                    }
   607→                }
   608→            } else { return -1; }
   609→
   610→            let mut new_string = String::new();
   611→            if let Some(ptr) = current.address_space.translate(VAddr::new(newpath), READABLE) {
   612→                let mut raw_ptr: *mut u8 = ptr.as_ptr();
   613→                loop {
   614→                    unsafe {
   615→                        let ch = *raw_ptr;
   616→                        if ch == 0 { break; }
   617→                        new_string.push(ch as char);
   618→                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
   619→                    }
   620→                }
   621→            } else { return -1; }
   622→
   623→            FS.link(&old_string, &new_string)
   624→        }
   625→
   626→        /// unlinkat 系统调用：删除硬链接
   627→        ///
   628→        /// TODO: 实现 unlinkat 系统调用（练习题）
   629→        fn unlinkat(&self, _caller: Caller, _dirfd: i32, path: usize, _flags: u32) -> isize {
   630→            let current = PROCESSOR.get_mut().current().unwrap();
   631→            const READABLE: VmFlags<Sv39> = build_flags("RV");
   632→
   633→            let mut string = String::new();
   634→            if let Some(ptr) = current.address_space.translate(VAddr::new(path), READABLE) {
   635→                let mut raw_ptr: *mut u8 = ptr.as_ptr();
   636→                loop {
   637→                    unsafe {
   638→                        let ch = *raw_ptr;
   639→                        if ch == 0 { break; }
   640→                        string.push(ch as char);
   641→                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
   642→                    }
   643→                }
   644→            } else { return -1; }
   645→
   646→            FS.unlink(&string)
   647→        }
   648→
   649→        /// fstat 系统调用：获取文件状态
   650→        ///
   651→        /// TODO: 实现 fstat 系统调用（练习题）
   652→        fn fstat(&self, _caller: Caller, fd: usize, st: usize) -> isize {
   653→            let current = PROCESSOR.get_mut().current().unwrap();
   654→            const WRITEABLE: VmFlags<Sv39> = build_flags("W_V");
   655→
   656→            if fd >= current.fd_table.len() || current.fd_table[fd].is_none() {
   657→                return -1;
   658→            }
   659→            if let Some(mut ptr) = current.address_space.translate::<Stat>(VAddr::new(st), WRITEABLE) {
   660→                let file = current.fd_table[fd].as_ref().unwrap().lock();
   661→                if let Some(inode) = &file.inode {
   662→                    let mut mode = StatMode::empty();
   663→                    if inode.is_dir() { mode |= StatMode::DIR; }
   664→                    if inode.is_file() { mode |= StatMode::FILE; }
   665→                    unsafe {
   666→                        *ptr.as_mut() = Stat {
   667→                            dev: 0,
   668→                            ino: inode.get_inode_id() as u64,
   669→                            mode,
   670→                            nlink: inode.get_nlink(),
   671→                            pad: [0; 7],
   672→                        };
   673→                    }
   674→                    0
   675→                } else {
   676→                    // standard in/out, mock values or error? Returning 0 with some default is safer.
   677→                    // But normally fstat on stdin/stdout works. I'll just return -1 for simplicity if not a file,
   678→                    // or let's check what test expects.
   679→                    -1
   680→                }
   681→            } else {
   682→                -1
   683→            }
   684→        }
   685→    }
   686→
   687→    /// 进程管理系统调用实现（与第五章基本相同）
   688→    impl Process for SyscallContext {
   689→        /// exit 系统调用
   690→        #[inline]
   691→        fn exit(&self, _caller: Caller, exit_code: usize) -> isize {
   692→            exit_code as isize
   693→        }
   694→
   695→        /// fork 系统调用：创建子进程（包含复制文件描述符表）
   696→        fn fork(&self, _caller: Caller) -> isize {
   697→            let processor: *mut PManager<ProcStruct, ProcManager> = PROCESSOR.get_mut() as *mut _;
   698→            let current = unsafe { (*processor).current().unwrap() };
   699→            let parent_pid = current.pid;
   700→            let mut child_proc = current.fork().unwrap();
   701→            let pid = child_proc.pid;
   702→            let context = &mut child_proc.context.context;
   703→            *context.a_mut(0) = 0 as _;
   704→            unsafe {
   705→                (*processor).add(pid, child_proc, parent_pid);
   706→            }
   707→            pid.get_usize() as isize
   708→        }
   709→
   710→        /// exec 系统调用：从文件系统加载新程序
   711→        ///
   712→        /// 与第五章不同：程序从 easy-fs 文件系统中读取，而非内存中的 APPS 表
   713→        fn exec(&self, _caller: Caller, path: usize, count: usize) -> isize {
   714→            const READABLE: VmFlags<Sv39> = build_flags("RV");
   715→            let current = PROCESSOR.get_mut().current().unwrap();
   716→            current
   717→                .address_space
   718→                .translate::<u8>(VAddr::new(path), READABLE)
   719→                .map(|ptr| unsafe {
   720→                    core::str::from_utf8_unchecked(core::slice::from_raw_parts(ptr.as_ptr(), count))
   721→                })
   722→                .and_then(|name| FS.open(name, OpenFlags::RDONLY))
   723→                .map_or_else(
   724→                    || {
   725→                        log::error!("unknown app, select one in the list: ");
   726→                        // 列出文件系统中所有可用程序
   727→                        FS.readdir("")
   728→                            .unwrap()
   729→                            .into_iter()
   730→                            .for_each(|app| println!("{app}"));
   731→                        println!();
   732→                        -1
   733→                    },
   734→                    |fd| {
   735→                        // 从文件系统读取完整 ELF 数据并加载
   736→                        current.exec(ElfFile::new(&read_all(fd)).unwrap());
   737→                        0
   738→                    },
   739→                )
   740→        }
   741→
   742→        /// wait 系统调用：等待子进程退出
   743→        fn wait(&self, _caller: Caller, pid: isize, exit_code_ptr: usize) -> isize {
   744→            let processor: *mut PManager<ProcStruct, ProcManager> = PROCESSOR.get_mut() as *mut _;
   745→            let current = unsafe { (*processor).current().unwrap() };
   746→            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
   747→            if let Some((dead_pid, exit_code)) =
   748→                unsafe { (*processor).wait(ProcId::from_usize(pid as usize)) }
   749→            {
   750→                if let Some(mut ptr) = current
   751→                    .address_space
   752→                    .translate::<i32>(VAddr::new(exit_code_ptr), WRITABLE)
   753→                {
   754→                    unsafe { *ptr.as_mut() = exit_code as i32 };
   755→                }
   756→                return dead_pid.get_usize() as isize;
   757→            } else {
   758→                return -1;
   759→            }
   760→        }
   761→
   762→        /// getpid 系统调用
   763→        fn getpid(&self, _caller: Caller) -> isize {
   764→            let current = PROCESSOR.get_mut().current().unwrap();
   765→            current.pid.get_usize() as _
   766→        }
   767→
   768→        /// spawn 系统调用（TODO 练习题）
   769→        fn spawn(&self, _caller: Caller, _path: usize, _count: usize) -> isize {
   770→            let current = PROCESSOR.get_mut().current().unwrap();
   771→            tg_console::log::info!(
   772→                "spawn: parent pid = {}, not implemented",
   773→                current.pid.get_usize()
   774→            );
   775→            -1
   776→        }
   777→
   778→        /// sbrk 系统调用：调整堆大小
   779→        fn sbrk(&self, _caller: Caller, size: i32) -> isize {
   780→            let current = PROCESSOR.get_mut().current().unwrap();
   781→            if let Some(old_brk) = current.change_program_brk(size as isize) {
   782→                old_brk as isize
   783→            } else {
   784→                -1
   785→            }
   786→        }
   787→    }
   788→
   789→    /// 调度系统调用实现
   790→    impl Scheduling for SyscallContext {
   791→        #[inline]
   792→        fn sched_yield(&self, _caller: Caller) -> isize {
   793→            0
   794→        }
   795→
   796→        /// set_priority 系统调用（TODO 练习题）
   797→        fn set_priority(&self, _caller: Caller, prio: isize) -> isize {
   798→            let current = PROCESSOR.get_mut().current().unwrap();
   799→            tg_console::log::info!(
   800→                "set_priority: pid = {}, prio = {}, not implemented",
   801→                current.pid.get_usize(),
   802→                prio
   803→            );
   804→            -1
   805→        }
   806→    }
   807→
   808→    /// 时钟系统调用实现
   809→    impl Clock for SyscallContext {
   810→        #[inline]
   811→        fn clock_gettime(&self, _caller: Caller, clock_id: ClockId, tp: usize) -> isize {
   812→            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
   813→            match clock_id {
   814→                ClockId::CLOCK_MONOTONIC => {
   815→                    if let Some(mut ptr) = PROCESSOR
   816→                        .get_mut()
   817→                        .current()
   818→                        .unwrap()
   819→                        .address_space
   820→                        .translate::<TimeSpec>(VAddr::new(tp), WRITABLE)
   821→                    {
   822→                        let time = riscv::register::time::read() * 10000 / 125;
   823→                        *unsafe { ptr.as_mut() } = TimeSpec {
   824→                            tv_sec: time / 1_000_000_000,
   825→                            tv_nsec: time % 1_000_000_000,
   826→                        };
   827→                        0
   828→                    } else {
   829→                        log::error!("ptr not readable");
   830→                        -1
   831→                    }
   832→                }
   833→                _ => -1,
   834→            }
   835→        }
   836→    }
   837→
   838→    /// 内存管理系统调用实现
   839→    impl Memory for SyscallContext {
   840→        /// mmap 系统调用（TODO 练习题）
   841→        fn mmap(
   842→            &self,
   843→            _caller: Caller,
   844→            addr: usize,
   845→            len: usize,
   846→            prot: i32,
   847→            _flags: i32,
   848→            _fd: i32,
   849→            _offset: usize,
   850→        ) -> isize {
   851→            tg_console::log::info!(
   852→                "mmap: addr = {addr:#x}, len = {len}, prot = {prot}, not implemented"
   853→            );
   854→            -1
   855→        }
   856→
   857→        /// munmap 系统调用（TODO 练习题）
   858→        fn munmap(&self, _caller: Caller, addr: usize, len: usize) -> isize {
   859→            tg_console::log::info!("munmap: addr = {addr:#x}, len = {len}, not implemented");
   860→            -1
   861→        }
   862→    }
   863→}
   864→
   865→/// 非 RISC-V64 架构的占位实现
   866→#[cfg(not(target_arch = "riscv64"))]
   867→mod stub {
   868→    use tg_kernel_vm::page_table::{MmuMeta, VmFlags};
   869→
   870→    /// Sv39 占位类型
   871→    #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
   872→    pub struct Sv39;
   873→
   874→    impl MmuMeta for Sv39 {
   875→        const P_ADDR_BITS: usize = 56;
   876→        const PAGE_BITS: usize = 12;
   877→        const LEVEL_BITS: &'static [usize] = &[9, 9, 9];
   878→        const PPN_POS: usize = 10;
   879→        #[inline]
   880→        fn is_leaf(value: usize) -> bool {
   881→            value & 0b1110 != 0
   882→        }
   883→    }
   884→
   885→    /// 构建 VmFlags 占位实现
   886→    pub const fn build_flags(_s: &str) -> VmFlags<Sv39> {
   887→        unsafe { VmFlags::from_raw(0) }
   888→    }
   889→
   890→    /// 解析 VmFlags 占位实现
   891→    pub fn parse_flags(_s: &str) -> Result<VmFlags<Sv39>, ()> {
   892→        Ok(unsafe { VmFlags::from_raw(0) })
   893→    }
   894→
   895→    /// 主机平台占位入口
   896→    #[unsafe(no_mangle)]
   897→    pub extern "C" fn main() -> i32 {
   898→        0
   899→    }
   900→
   901→    /// libc 启动占位
   902→    #[unsafe(no_mangle)]
   903→    pub extern "C" fn __libc_start_main() -> i32 {
   904→        0
   905→    }
   906→
   907→    /// 异常处理占位
   908→    #[unsafe(no_mangle)]
   909→    pub extern "C" fn rust_eh_personality() {}
   910→}
   911→

