    95→// 定义内核入口点，设置启动栈大小为 32 页 = 128 KiB。
    96→//
    97→// 这里不再调用 tg_linker::boot0! 宏，避免外部已发布版本与 Rust 2024
    98→// 在属性语义上的兼容差异影响本 crate 的发布校验。
    99→#[cfg(target_arch = "riscv64")]
   100→#[unsafe(naked)]
   101→#[unsafe(no_mangle)]
   102→#[unsafe(link_section = ".text.entry")]
   103→unsafe extern "C" fn _start() -> ! {
   104→    const STACK_SIZE: usize = 32 * 4096;
   105→    #[unsafe(link_section = ".boot.stack")]
   106→    static mut STACK: [u8; STACK_SIZE] = [0u8; STACK_SIZE];
   107→
   108→    core::arch::naked_asm!(
   109→        "la sp, {stack} + {stack_size}",
   110→        "j  {main}",
   111→        stack = sym STACK,
   112→        stack_size = const STACK_SIZE,
   113→        main = sym rust_main,
   114→    )
   115→}
