   151→/// VirtIO MMIO 设备地址范围
   152→///
   153→/// QEMU virt 平台上 VirtIO 块设备的 MMIO 基地址为 0x1000_1000，大小 0x1000。
   154→/// 需要在内核地址空间中进行恒等映射，以便驱动程序访问。
   155→pub const MMIO: &[(usize, usize)] = &[(0x1000_1000, 0x00_1000)];
   156→
   157→/// 内核主函数——系统初始化和启动入口
   158→///
   159→/// 执行流程：
   160→/// 1. 清零 BSS 段
   161→/// 2. 初始化控制台和日志系统
   162→/// 3. 初始化内核堆分配器
   163→/// 4. 分配并创建异界传送门
   164→/// 5. 建立内核地址空间（恒等映射 + MMIO 映射 + 传送门映射），激活 Sv39 分页
   165→/// 6. 初始化异界传送门和系统调用处理器
   166→/// 7. 从文件系统加载初始进程 `initproc`，进入调度循环
   167→extern "C" fn rust_main() -> ! {
   168→    let layout = tg_linker::KernelLayout::locate();
   169→    // 步骤 1：清零 BSS 段
   170→    unsafe { layout.zero_bss() };
   171→    // 步骤 2：初始化控制台输出和日志系统
   172→    tg_console::init_console(&Console);
   173→    tg_console::set_log_level(option_env!("LOG"));
   174→    tg_console::test_log();
   175→    // 步骤 3：初始化内核堆分配器
   176→    tg_kernel_alloc::init(layout.start() as _);
   177→    unsafe {
   178→        tg_kernel_alloc::transfer(core::slice::from_raw_parts_mut(
   179→            layout.end() as _,
   180→            MEMORY - layout.len(),
   181→        ))
   182→    };
   183→    // 步骤 4：分配异界传送门所需的物理页面
   184→    let portal_size = MultislotPortal::calculate_size(1);
   185→    let portal_layout = Layout::from_size_align(portal_size, 1 << Sv39::PAGE_BITS).unwrap();
   186→    let portal_ptr = unsafe { alloc(portal_layout) };
   187→    assert!(portal_layout.size() < 1 << Sv39::PAGE_BITS);
   188→    // 步骤 5：建立内核地址空间并激活 Sv39 分页（包含 MMIO 映射）
   189→    kernel_space(layout, MEMORY, portal_ptr as _);
   190→    // 步骤 6：初始化异界传送门
   191→    let portal = unsafe { MultislotPortal::init_transit(PROTAL_TRANSIT.base().val(), 1) };
   192→    // 步骤 7：初始化系统调用处理器
   193→    tg_syscall::init_io(&SyscallContext);
   194→    tg_syscall::init_process(&SyscallContext);
   195→    tg_syscall::init_scheduling(&SyscallContext);
   196→    tg_syscall::init_clock(&SyscallContext);
   197→    tg_syscall::init_memory(&SyscallContext);
   198→    // 步骤 8：从文件系统加载初始进程 initproc
   199→    // 与第五章不同：程序从磁盘镜像（fs.img）中读取，而非内核内嵌
   200→    let initproc = read_all(FS.open("initproc", OpenFlags::RDONLY).unwrap());
   201→    if let Some(process) = Process::from_elf(ElfFile::new(initproc.as_slice()).unwrap()) {
   202→        PROCESSOR.get_mut().set_manager(ProcManager::new());
   203→        PROCESSOR
   204→            .get_mut()
   205→            .add(process.pid, process, ProcId::from_usize(usize::MAX));
   206→    }
   207→
   208→    // ─── 主调度循环 ───
   209→    loop {
   210→        let processor: *mut PManager<Process, ProcManager> = PROCESSOR.get_mut() as *mut _;
   211→        if let Some(task) = unsafe { (*processor).find_next() } {
   212→            // 通过异界传送门切换到用户地址空间执行用户程序
   213→            unsafe { task.context.execute(portal, ()) };
   214→
   215→            // ─── Trap 返回后处理 ───
   216→            match scause::read().cause() {
   217→                // ─── 系统调用（ecall 指令触发） ───
   218→                scause::Trap::Exception(scause::Exception::UserEnvCall) => {
   219→                    use tg_syscall::{SyscallId as Id, SyscallResult as Ret};
   220→                    let ctx = &mut task.context.context;
   221→                    ctx.move_next();
   222→                    let id: Id = ctx.a(7).into();
   223→                    let args = [ctx.a(0), ctx.a(1), ctx.a(2), ctx.a(3), ctx.a(4), ctx.a(5)];
   224→                    match tg_syscall::handle(Caller { entity: 0, flow: 0 }, id, args) {
   225→                        Ret::Done(ret) => match id {
   226→                            Id::EXIT => unsafe { (*processor).make_current_exited(ret) },
   227→                            _ => {
   228→                                let ctx = &mut task.context.context;
   229→                                *ctx.a_mut(0) = ret as _;
   230→                                unsafe { (*processor).make_current_suspend() };
   231→                            }
   232→                        },
   233→                        Ret::Unsupported(_) => {
   234→                            log::info!("id = {id:?}");
   235→                            unsafe { (*processor).make_current_exited(-2) };
   236→                        }
   237→                    }
   238→                }
   239→                // ─── 其他异常/中断：杀死进程 ───
   240→                e => {
   241→                    log::error!("unsupported trap: {e:?}");
   242→                    unsafe { (*processor).make_current_exited(-3) };
   243→                }
   244→            }
   245→        } else {
   246→            println!("no task");
   247→            break;
   248→        }
   249→    }
   250→
   251→    tg_sbi::shutdown(false)
   252→}
