        }
    }

    // ─── 系统调用实现 ───

    /// 系统调用上下文
    pub struct SyscallContext;

    /// 可读权限标志（用于地址翻译时的权限检查）
    const READABLE: VmFlags<Sv39> = build_flags("RV");
    /// 可写权限标志
    const WRITEABLE: VmFlags<Sv39> = build_flags("W_V");

    /// IO 系统调用实现：read、write、open、close
    ///
    /// 与第五章的关键区别：
    /// - read/write 不仅支持标准 I/O，还支持通过文件描述符读写文件
    /// - 新增 open/close 系统调用，通过 easy-fs 打开磁盘上的文件
    impl IO for SyscallContext {
        /// write 系统调用：写入文件或标准输出
        ///
        /// - fd == STDOUT/STDDEBUG：直接通过控制台输出
        /// - 其他 fd：通过文件描述符表查找文件句柄，写入文件
        fn write(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            if let Some(ptr) = current
                .address_space
                .translate::<u8>(VAddr::new(buf), READABLE)
            {
                if fd == STDOUT || fd == STDDEBUG {
                    // 标准输出：直接打印到控制台
                    print!("{}", unsafe {
                        core::str::from_utf8_unchecked(core::slice::from_raw_parts(
                            ptr.as_ptr(),
                            count,
                        ))
                    });
                    count as _
                } else if let Some(file) = &current.fd_table[fd] {
                    // 普通文件：通过文件句柄写入
                    let file = file.lock();
                    if file.writable() {
                        let mut v: Vec<&'static mut [u8]> = Vec::new();
                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
                        file.write(UserBuffer::new(v)) as _
                    } else {
                        log::error!("file not writable");
                        -1
                    }
                } else {
                    log::error!("unsupported fd: {fd}");
                    -1
                }
            } else {
                log::error!("ptr not readable");
                -1
            }
        }

        /// read 系统调用：从文件或标准输入读取
        ///
        /// - fd == STDIN：通过 SBI console_getchar 逐字符读取
        /// - 其他 fd：通过文件句柄从磁盘文件读取
        fn read(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            if let Some(ptr) = current
                .address_space
                .translate::<u8>(VAddr::new(buf), WRITEABLE)
            {
                if fd == STDIN {
                    // 标准输入：通过 SBI 逐字符读取
                    let mut ptr = ptr.as_ptr();
                    for _ in 0..count {
                        unsafe {
                            *ptr = tg_sbi::console_getchar() as u8;
                            ptr = ptr.add(1);
                        }
                    }
                    count as _
                } else if let Some(file) = &current.fd_table[fd] {
                    // 普通文件：通过文件句柄读取
                    let file = file.lock();
                    if file.readable() {
                        let mut v: Vec<&'static mut [u8]> = Vec::new();
                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
                        file.read(UserBuffer::new(v)) as _
                    } else {
                        log::error!("file not readable");
                        -1
                    }
                } else {
                    log::error!("unsupported fd: {fd}");
                    -1
                }
            } else {
                log::error!("ptr not writeable");
                -1
            }
        }

        /// open 系统调用：打开文件
        ///
        /// 从用户空间读取文件路径（以 '\0' 结尾的字符串），
        /// 通过 easy-fs 文件系统打开文件，分配新的文件描述符。
        fn open(&self, _caller: Caller, path: usize, flags: usize) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            if let Some(ptr) = current.address_space.translate(VAddr::new(path), READABLE) {
                // 从用户空间逐字符读取文件路径（需要地址翻译）
                let mut string = String::new();
                let mut raw_ptr: *mut u8 = ptr.as_ptr();
                loop {
                    unsafe {
                        let ch = *raw_ptr;
                        if ch == 0 {
                            break;
                        }
                        string.push(ch as char);
                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
                    }
                }

                // 通过文件系统打开文件，分配新的文件描述符
                if let Some(fd) =
                    FS.open(string.as_str(), OpenFlags::from_bits(flags as u32).unwrap())
                {
                    let new_fd = current.fd_table.len();
                    current.fd_table.push(Some(Mutex::new(fd.as_ref().clone())));
                    new_fd as isize
                } else {
                    -1
                }
            } else {
                log::error!("ptr not writeable");
                -1
            }
        }

        /// close 系统调用：关闭文件描述符
        #[inline]
        fn close(&self, _caller: Caller, fd: usize) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            if fd >= current.fd_table.len() || current.fd_table[fd].is_none() {
                return -1;
            }
            current.fd_table[fd].take();
            0
        }

        /// linkat 系统调用：创建硬链接
        ///
        /// TODO: 实现 linkat 系统调用（练习题）
        fn linkat(
            &self,
            _caller: Caller,
            _olddirfd: i32,
            oldpath: usize,
            _newdirfd: i32,
            newpath: usize,
            _flags: u32,
        ) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            const READABLE: VmFlags<Sv39> = build_flags("RV");

            let mut old_string = String::new();
            if let Some(ptr) = current
                .address_space
                .translate(VAddr::new(oldpath), READABLE)
            {
                let mut raw_ptr: *mut u8 = ptr.as_ptr();
                loop {
                    unsafe {
                        let ch = *raw_ptr;
                        if ch == 0 {
                            break;
                        }
                        old_string.push(ch as char);
                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
                    }
                }
            } else {
                return -1;
            }

            let mut new_string = String::new();
            if let Some(ptr) = current
                .address_space
                .translate(VAddr::new(newpath), READABLE)
            {
                let mut raw_ptr: *mut u8 = ptr.as_ptr();
                loop {
                    unsafe {
                        let ch = *raw_ptr;
                        if ch == 0 {
                            break;
                        }
                        new_string.push(ch as char);
                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
                    }
                }
            } else {
                return -1;
            }

            FS.link(&old_string, &new_string)
        }

        /// unlinkat 系统调用：删除硬链接
        ///
        /// TODO: 实现 unlinkat 系统调用（练习题）
        fn unlinkat(&self, _caller: Caller, _dirfd: i32, path: usize, _flags: u32) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            const READABLE: VmFlags<Sv39> = build_flags("RV");

            let mut string = String::new();
            if let Some(ptr) = current.address_space.translate(VAddr::new(path), READABLE) {
                let mut raw_ptr: *mut u8 = ptr.as_ptr();
                loop {
                    unsafe {
                        let ch = *raw_ptr;
                        if ch == 0 {
                            break;
                        }
                        string.push(ch as char);
                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
                    }
                }
            } else {
                return -1;
            }

            FS.unlink(&string)
        }

        /// fstat 系统调用：获取文件状态
        ///
        /// TODO: 实现 fstat 系统调用（练习题）
        fn fstat(&self, _caller: Caller, fd: usize, st: usize) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            const WRITEABLE: VmFlags<Sv39> = build_flags("W_V");

            if fd >= current.fd_table.len() || current.fd_table[fd].is_none() {
                return -1;
            }
            if let Some(mut ptr) = current
                .address_space
                .translate::<Stat>(VAddr::new(st), WRITEABLE)
            {
                let file = current.fd_table[fd].as_ref().unwrap().lock();
                if let Some(inode) = &file.inode {
                    let mut mode = StatMode::empty();
                    if inode.is_dir() {
                        mode |= StatMode::DIR;
                    }
                    if inode.is_file() {
                        mode |= StatMode::FILE;
                    }
                    unsafe {
                        let mut stat: Stat = core::mem::zeroed();
                        stat.dev = 0;
                        stat.ino = inode.get_inode_id() as u64;
                        stat.mode = mode;
                        stat.nlink = inode.get_nlink();
                        *ptr.as_mut() = stat;
                    }
                    0
                } else {
                    // standard in/out, mock values or error? Returning 0 with some default is safer.
                    // But normally fstat on stdin/stdout works. I'll just return -1 for simplicity if not a file,
                    // or let's check what test expects.
                    -1
                }
            } else {
                -1
            }
        }
    }

    /// 进程管理系统调用实现（与第五章基本相同）
    impl Process for SyscallContext {
        /// exit 系统调用
        #[inline]
        fn exit(&self, _caller: Caller, exit_code: usize) -> isize {
            exit_code as isize
        }

        /// fork 系统调用：创建子进程（包含复制文件描述符表）
        fn fork(&self, _caller: Caller) -> isize {
            let processor: *mut PManager<ProcStruct, ProcManager> = PROCESSOR.get_mut() as *mut _;
            let current = unsafe { (*processor).current().unwrap() };
            let parent_pid = current.pid;
            let mut child_proc = current.fork().unwrap();
            let pid = child_proc.pid;
            let context = &mut child_proc.context.context;
            *context.a_mut(0) = 0 as _;
            unsafe {
                (*processor).add(pid, child_proc, parent_pid);
            }
            pid.get_usize() as isize
        }

        /// exec 系统调用：从文件系统加载新程序
        ///
        /// 与第五章不同：程序从 easy-fs 文件系统中读取，而非内存中的 APPS 表
        fn exec(&self, _caller: Caller, path: usize, count: usize) -> isize {
            const READABLE: VmFlags<Sv39> = build_flags("RV");
            let current = PROCESSOR.get_mut().current().unwrap();
            current
                .address_space
                .translate::<u8>(VAddr::new(path), READABLE)
                .map(|ptr| unsafe {
                    core::str::from_utf8_unchecked(core::slice::from_raw_parts(ptr.as_ptr(), count))
                })
                .and_then(|name| FS.open(name, OpenFlags::RDONLY))
                .map_or_else(
                    || {
                        log::error!("unknown app, select one in the list: ");
                        // 列出文件系统中所有可用程序
                        FS.readdir("")
                            .unwrap()
                            .into_iter()
                            .for_each(|app| println!("{app}"));
                        println!();
                        -1
                    },
                    |fd| {
                        // 从文件系统读取完整 ELF 数据并加载
                        current.exec(ElfFile::new(&read_all(fd)).unwrap());
                        0
                    },
                )
        }

        /// wait 系统调用：等待子进程退出
        fn wait(&self, _caller: Caller, pid: isize, exit_code_ptr: usize) -> isize {
            let processor: *mut PManager<ProcStruct, ProcManager> = PROCESSOR.get_mut() as *mut _;
            let current = unsafe { (*processor).current().unwrap() };
            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
            if let Some((dead_pid, exit_code)) =
                unsafe { (*processor).wait(ProcId::from_usize(pid as usize)) }
            {
                if let Some(mut ptr) = current
                    .address_space
                    .translate::<i32>(VAddr::new(exit_code_ptr), WRITABLE)
                {
                    unsafe { *ptr.as_mut() = exit_code as i32 };
                }
                return dead_pid.get_usize() as isize;
            } else {
                return -1;
            }
        }

        /// getpid 系统调用
        fn getpid(&self, _caller: Caller) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            current.pid.get_usize() as _
        }

        /// spawn 系统调用
        fn spawn(&self, _caller: Caller, path: usize, count: usize) -> isize {
            const READABLE: VmFlags<Sv39> = build_flags("RV");
            let processor: *mut PManager<ProcStruct, ProcManager> = PROCESSOR.get_mut() as *mut _;
            let current = unsafe { (*processor).current().unwrap() };
            let parent_pid = current.pid;

            current
                .address_space
                .translate::<u8>(VAddr::new(path), READABLE)
                .map(|ptr| unsafe {
                    core::str::from_utf8_unchecked(core::slice::from_raw_parts(ptr.as_ptr(), count))
                })
                .and_then(|name| FS.open(name, OpenFlags::RDONLY))
                .map_or_else(
                    || {
                        log::error!("unknown app");
                        -1
                    },
                    |fd| {
                        if let Some(child_proc) =
                            ProcStruct::from_elf(ElfFile::new(&read_all(fd)).unwrap())
                        {
                            let pid = child_proc.pid;
                            unsafe {
                                (*processor).add(pid, child_proc, parent_pid);
                            }
                            pid.get_usize() as isize
                        } else {
                            -1
                        }
                    },
                )
        }

        /// sbrk 系统调用：调整堆大小
        fn sbrk(&self, _caller: Caller, size: i32) -> isize {
            let current = PROCESSOR.get_mut().current().unwrap();
            if let Some(old_brk) = current.change_program_brk(size as isize) {
                old_brk as isize
            } else {
                -1
            }
        }
    }

    /// 调度系统调用实现
    impl Scheduling for SyscallContext {
        #[inline]
        fn sched_yield(&self, _caller: Caller) -> isize {
            0
        }

        /// set_priority 系统调用
        fn set_priority(&self, _caller: Caller, prio: isize) -> isize {
            if prio < 2 {
                return -1;
            }
            prio
        }
    }

    /// 时钟系统调用实现
    impl Clock for SyscallContext {
        #[inline]
        fn clock_gettime(&self, _caller: Caller, clock_id: ClockId, tp: usize) -> isize {
            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
            match clock_id {
                ClockId::CLOCK_MONOTONIC => {
                    if let Some(mut ptr) = PROCESSOR
                        .get_mut()
                        .current()
                        .unwrap()
                        .address_space
                        .translate::<TimeSpec>(VAddr::new(tp), WRITABLE)
                    {
                        let time = riscv::register::time::read() * 10000 / 125;
                        *unsafe { ptr.as_mut() } = TimeSpec {
                            tv_sec: time / 1_000_000_000,
                            tv_nsec: time % 1_000_000_000,
                        };
                        0
                    } else {
                        log::error!("ptr not readable");
                        -1
                    }
                }
                _ => -1,
            }
        }
    }

    /// 内存管理系统调用实现
    impl Memory for SyscallContext {
        /// mmap 系统调用
        fn mmap(
            &self,
            _caller: Caller,
            addr: usize,
            len: usize,
            prot: i32,
            _flags: i32,
            _fd: i32,
            _offset: usize,
        ) -> isize {
            if addr % 4096 != 0 || (prot & !0x7) != 0 || prot == 0 {
                return -1;
            }
            let mut pte_flags: u8 = 0x11; // V_U
            if (prot & 1) != 0 {
                pte_flags |= 2;
            } // R
            if (prot & 2) != 0 {
                pte_flags |= 4;
            } // W
            if (prot & 4) != 0 {
                pte_flags |= 8;
            } // X
            let vm_flags = unsafe { VmFlags::from_raw(pte_flags as usize) };

            let processor: *mut PManager<ProcStruct, ProcManager> = PROCESSOR.get_mut() as *mut _;
            let current = unsafe { (*processor).current().unwrap() };

            let vpn_start = VPN::<Sv39>::new(addr >> 12);
            let pages_needed = (len + 4095) / 4096;
            let vpn_end = VPN::<Sv39>::new(vpn_start.val() + pages_needed);
            let range = vpn_start..vpn_end;

            for area in &current.address_space.areas {
                if area.start < range.end && area.end > range.start {
                    return -1;
                }
            }
            current.address_space.map(range, &[], 0, vm_flags);
            0
        }

        /// munmap 系统调用
        fn munmap(&self, _caller: Caller, addr: usize, len: usize) -> isize {
            if addr % 4096 != 0 {
                return -1;
            }
            let vpn_start = VPN::<Sv39>::new(addr >> 12);
            let pages_needed = (len + 4095) / 4096;
            let vpn_end = VPN::<Sv39>::new(vpn_start.val() + pages_needed);
            let range = vpn_start..vpn_end;

            let processor: *mut PManager<ProcStruct, ProcManager> = PROCESSOR.get_mut() as *mut _;
            let current = unsafe { (*processor).current().unwrap() };

            let mut found = false;
            for area in &current.address_space.areas {
                if area.start <= range.start && area.end >= range.end {
                    found = true;
                    break;
                }
            }
            if !found {
                return -1;
            }
            current.address_space.unmap(range);
            0
        }
    }
}

