#![allow(clippy::println_empty_string)]

extern crate alloc;

#[macro_use]
extern crate user_lib;
--
    println!("Rust user shell");
    let mut line: String = String::new(); // 记录着当前输入的命令
    print!(">> ");
    loop {
        let c = getchar();
        match c {
            LF | CR => {
                // 换行
                println!();
                if !line.is_empty() {
                    let pid = fork();
                    if pid == 0 {
                        // child process
                        // 子进程通过 exec 覆盖自身映像执行新程序。
--
                            println!("Error when executing!");
                            return -4;
                        }
                        unreachable!();
                    } else {
                        // 父进程等待子进程完成，打印退出信息。
--
                        println!("Shell: Process {} exited with code {}", pid, exit_code);
                    }
                    line.clear();
                }
                print!(">> ");
            }
            BS | DL => {
                // backspace
                if !line.is_empty() {
                    print!("{}", BS as char);
                    print!(" ");
                    print!("{}", BS as char);
                    line.pop();
                }
            }
            _ => {
                print!("{}", c as char);
                line.push(c as char);
            }
        }
    }
}

